def transform(grid):
    h, w = len(grid), len(grid[0])
    # The separator lattice is at the regularly repeated rows/columns;
    # the large repeated interior color is the output's default.
    from collections import Counter
    default = Counter(v for row in grid for v in row).most_common(1)[0][0]

    rs = [r for r in range(h) if sum(v != default for v in grid[r]) > w // 2]
    cs = [c for c for c in range(w) if sum(grid[r][c] != default for r in range(h)) > h // 2]

    def stride(lines):
        return min(b - a for a, b in zip(lines, lines[1:]))

    dr, dc = stride(rs), stride(cs)
    rs = [r for r in rs if (r - rs[0]) % dr == 0]
    cs = [c for c in cs if (c - cs[0]) % dc == 0]

    # Each junction matrix is the compressed representation. The repeated
    # tile color is the default; keep the marker color at each junction.
    return [
        [grid[rs[i]][cs[j]] if grid[rs[i]][cs[j]] != default else default
         for j in range(len(cs) - 1)]
        for i in range(len(rs) - 1)
    ]
